using JuMP
using GLPK

m = Model()
set_optimizer(m, GLPK.Optimizer)

@variable(m, q1 >= 0)
@variable(m, q2 >= 0)
@constraint(m, 2q1 + 5q2 <= 30)
@constraint(m, 4q1 + 2q2 <= 20)
@objective(m, Max, 3q1 + 4q2)

optimize!(m)

P := \min_{x \in \RR^n} \, c^\top x  
    \; \text{ subject to } \;
    A x = b  \text{ and } x \geq 0.

\begin{pmatrix}
        m_1 & m_2 & m_3 & 1 & 0 \\
        \ell_1 & \ell_2 & \ell_3 & 0 & 1 
    \end{pmatrix}
    \begin{pmatrix}
        q_1 \\
        q_2 \\
        q_3 \\
        s_m \\
        s_\ell
    \end{pmatrix}
    =
    \begin{pmatrix}
        M \\
        L
    \end{pmatrix}
      \quad \text{and} \quad
      x \geq 0.

D = \max_{\theta \in \RR^m} \, b^\top \theta
    \; \text{ subject to } \;
    A^\top \theta \leq c.

D =
    \max_{\theta \in \RR^m}
    \min_{x \in E} \; L(x, \theta)
    \; \text{ where } \;
    L(x, \theta) 
        := c^\top x + \theta^\top (b - A x)

\vecop
    \begin{pmatrix}
        a_{11} & a_{12} 
        \\
        a_{21} & a_{22} 
    \end{pmatrix}
    = 
    \begin{pmatrix}
        a_{11} \\
        a_{21} \\
        a_{12} \\
        a_{22}
    \end{pmatrix}
    .

\max_{w, \, p}
    \left\{
        p^\top \psi - w^\top \phi
    \right\}
    \; \text{ subject to } \;
    p^\top (I_m \otimes \1_n^\top)
    - w^\top (\1_m^\top \otimes I_n)
    \leq \vecop(c)^\top

A = (a_{i k})
   \quad \text{with} \quad
   a_{i k}
   :=
   \begin{cases}
       \; 1 & \text{if } e_k \text{ leaves } i \\
       -1   & \text{if } e_k \text{ enters } i \\
       \; 0 & \text{otherwise}.
   \end{cases}

\min \inner{c, q} 
    \quad \st \quad
    q \geq 0
    \; \text{ and } \;
    A q = b.
